quests[93313] = { id = 93313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight (90) E" }
quests[93339] = { id = 93339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trinket Trading", description = "I've never seen murlocs dis vicious. A few of dem are holdin' something feathered dat glints green. Dat might be de source of de darkness I sense.\n\nWhen you're out among de ruins, keep your eyes open for these objects. I think de murlocs unearthed somethin' dat's got them going mad.", sourceObjective = "Collect 8 Feathered Trinkets in the mire.", progress = "I know Zawadi thinks my presence here's a waste of time, even though we took down Ophidia. If I prove dat de murlocs have discovered something nefarious, she will have to admit I was right to come along.\n\nThese ruins are ancient. Who knows what might've sunk into de mire, only to be dug up by their greedy hands.", completion = "Interesting. Dey seem to be fetishes created by de snake creatures. Could dey be de source of de madness?\n\n<Wa'kani cups one of the trinkets in her hands, concentrating. After a few moments, she sighs.>\n\nNothing. I sense no lingerin' magics. These trinkets are not de cause. I suspected as much.", sourceObjectiveStatus = "unverified-source-field" }
quests[93340] = { id = 93340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Shard", description = "I thought de murlocs were driven into their frenzy by de trinkets, but they're just baubles made by de snakes. Once we drew closer to dat lighthouse, I began to suspect dey were not de cause.\n\nI can feel it from here. A pulsing darkness. Ancient. If you go up there, you may find de true source of de murlocs' madness.", sourceObjective = "Destroy the source of the murlocs' madness.", progress = "Your time was not wasted in gathering de trinkets. We were able to narrow down de source once we ruled them out!\n\nThat aside, I have never felt anything like de ripples of darkness coming from dat tower. Find and destroy whatever it is dat's controlling de murlocs.", completion = "So de murloc chieftain had a shadow-filled crystal? I wonder...\n\nIt is possible dat de murlocs unearthed dis ancient relic and dat its power consumed dem. A pity it was destroyed. I would have liked to study it.\n\nNdamu is a great loss, but de work you did here today means her sacrifice was not in vain. De snakes have been dealt a solid blow, de murlocs should start calming down, and we destroyed de source of de dark energy. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[93365] = { id = 93365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight (81-89) E" }
