quests[93372] = { id = 93372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Shadow Enclave", description = "The perfidious cultists of the Twilight's Blade have infiltrated Eversong and set up their horrid operations in a nearby cavern. Clear them out before they spread any further!", completion = "Good job and good riddance.", objectives = "Complete the Shadow Enclave delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
