quests[93382] = { id = 93382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pardon the Interruption", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly disrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", completion = "Great work! Now I should have time to fix whatever bug actually caused this in the first place.\n\nMaybe I can just say it's a feature and call it a day!", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 3 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93384] = { id = 93384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Collegiate Calamity", description = "The arcane tome, clearly agitated by something, bears the mark of Silvermoon's Thalassian University.\n\nIt could be worth investigating.", progress = "Is something amiss at the university?", completion = "Thank you, {name}. The situation was hardly conducive to study.", objectives = "Complete the Collegiate Calamity delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93385] = { id = 93385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: The Darkway", description = "Remnants of the Twilights Blade scurry like rats through the Arcway tunnels beneath Suramar.\n\nExterminate the vermin before they spread.", objectives = "Complete The Darkway delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93386] = { id = 93386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Parhelion Plaza", description = "Adventurers! Quel'Danas is once more under attack by the Void, and any who are able to provide assistance should head to the battlements of Parhelion Plaza to help stem the tide.", objectives = "Complete the Parhelion Plaza delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93387] = { id = 93387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dealing with Pests", description = "Every time I leave my hut, I return to a mess and soggy little murloc footprints.\n\nI am plannin' a different approach to deal with those pestersome amphibian encroachers, but I need to sort out some ingredients.\n\nWhile I work out my list for those pests--there is a ghost named Jelvik dat keeps after me for somethin'. Tell him to move along.", sourceObjective = "Confront Jelvik for Ofi the Sly.", progress = "What do you mean you don't see a ghost?", completion = "At this point, it's a game.\n\nI know he's there. He knows I know he's there, but if I keep pretendin' I don't see him, I win dis round!\n\nI wouldn't hate it if you helped him, though. Then we both win. Don't you tell him I said it.", sourceObjectiveStatus = "unverified-source-field" }
quests[93388] = { id = 93388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unusual Alchemy", description = "My list is ready. I need you to gather de ingredients to keep dem murlocs away for good.\n\nFirst, talk to Maka de Trawler. He and de kelpweaver from Torga's Beak like to catch fish in de inlet. Bring me some fish guts--disgustin' and perfect.\n\nNext, head out to Mlurkkr Mire. I need dat dirty ol' pearl dey think is so special.\n\nWhile you're in de Mire, relieve some of dem irritatin' serpent folk of some scales.\n\nMind you, I only want de good ones.", sourceObjective = "Gather a Pile of Fish Guts, the Tarnished Pearl, and 5 Undamaged Serpent Scales and bring them to Ofi's Hut.", progress = "Did you bring de goods?", completion = "You're a useful creature!\n\nI have ghosts dat harass me and murlocs makin' a mess every time I leave my hut. If de pests were not pesterin', dey wouldn't be pests, would dey?\n\nI can tell--you're gonna be de one to solve my problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[93389] = { id = 93389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocksblood", description = "I've been here so long dat pieces of my memory are lost to time. I feel an emptiness for something I loved.\n\nThere will be no rest for me until I know who or what it was. I can only remember one word... Rocksblood. I don't know who or what dat is.\n\nCheck de murloc ruins to de south. There's someone who can point you in de right direction.\n\nSince Ofi is bein' stubborn, I need you to help me remember.", sourceObjective = "Find the clues to unlock Jelvik's missing memory.", completion = "These pieces are comin' together... I almost have it. Get back to Ofi. I need to ponder dis for a bit.\n\nI feel hope again, {class}. You did dis, and I give you my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[93390] = { id = 93390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Acceptable Apprentice", description = "Dis part is gonna be fun.\n\nI got de mixture started. It is already unpleasant, but now we will make it really vile.\n\nWhen you feel mentally prepared to be a useful one again, let me know.", sourceObjective = "Speak to Ofi when you are ready to create a Pungent Concoction.", progress = "You feelin' challenged?", completion = "Oosha! Dat is potent. I did not know your strength.\n\nAt least there was no explosion dis time.\n\nNot bad, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[93391] = { id = 93391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make it Stinky", description = "Best you move our little deterrents out to de strip of land between my home and de maniacs' mire.\n\nThey may try to stop you, but hold fast. If it works, dey will be running with their tails between their legs.\n\nDo murlocs even have tails?", sourceObjective = "Place 3 Murloc Deterrents between Ofi's Hut and Mlurkkr Mire.", progress = "Have de murlocs moved on?", completion = "Ha! Well done. Dat should keep dem runnin' for a while.\n\nI do love de smell of chaos in de morning. \n\nOf course, it could also be you. Could you stand back a ways?", sourceObjectiveStatus = "unverified-source-field" }
quests[93392] = { id = 93392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recovering Memories", description = "To de northeast, there's a small island. I remember long ago a great roarin' and howlin' dat echoed across de waters.\n\nI could hear de anger, but there was also pain. I could not venture to dat place. What if I became lost, my own feelings swallowed by de bigger ones?\n\nOne day, it became quiet again, but now I feel dis is de final key to de lock on my soul.\n\nGo there. Find de last piece.", sourceObjective = "Defeat the Lonely Beast and find Jelvik's missing memory.", progress = "Did you find it?", completion = "I may weep from de joy dat has filled my spirit. I thought she was gone so long ago dat even she eventually moved on from my mind.\n\nNow my sweet Sava will be with me forever.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[93393] = { id = 93393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Kindness", description = "You know, my friend, as happy as I am... I keep thinkin' how sad we made dat beast. I do not wish dat feelin' on another livin' soul.\n\nHe took care of dear Sava for all de years she was lost. Could you help us with one last request?\n\nIf you could bring him a friend of his own, it will repay our debt.\n\nThen we can move on once and for all--me and Sava will be free.", sourceObjective = "Question Ofi the Sly and help the Lonely Beast.", progress = "Don't you tell anyone about my part in all of dat. \n\nIf folks start thinkin' I'm soft, they'll never leave me alone.", completion = "Now our game is over. I'm guessin' it's gonna be quieter around here with my friend gone.\n\nWhat? I'm always pretendin' my friends don't exist. Who are you? Ha!\n\nAh, it looks like one of de small ones preferred your company to dat of de beast. You best take him with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[93396] = { id = 93396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bursting at the Seams", description = "Veraan... alive...\n\n<Kifaan shakes his head in disbelief.>\n\nI've spent countless hours running this moment through my head, but now that it's here, I find myself grasping for words...\n\nThe Shadowguard attempted to raise Dimensius to power... they've sworn fealty to Xal'atath as she wages war on worlds. Am I supposed to just... pretend none of that happened? Is THAT what my oaths to family require?\n\nAnd what of Veraan? Does she regret her involvement?\n\nI should check on her.", completion = "I've been focusing on my own feelings so much that I never stopped to think about how Veraan might feel.\n\nI may not have fared any better had they pumped ME full of Void.", objectives = "Help Kifaan check on his sister's well-being.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93397] = { id = 93397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnawing Hunger" }
quests[93409] = { id = 93409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Atal'Aman", description = "<The fallen scout's body bears terrible wounds, but still clutches tightly to a report detailing an immanent Vilebranch attack on Atal'Aman.>", completion = "Good. They should learn to stay in their holes.", objectives = "Complete the Atal'Aman delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93410] = { id = 93410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Twilight Crypts", description = "The ancient Amani crypts near the Broken Throne have been overrun.\n\nClear them of interlopers before the dead within can be defiled further.", completion = "One day Zul'Aman will be free of their taint.", objectives = "Complete the Twilight Crypts delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93413] = { id = 93413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TO DEPRECATE Battle for Zul'jarra", description = "Zul'jan is the one who did this to Zul'jarra. He needs to answer for what he did to his sister.\n\nNow, we gather Zul'jarra's forces. Let them know that her hash'uras have come once again to aid the Amani.", sourceObjective = "Talk to Liadrin at the Gate of the Eastern Fang.", sourceObjectiveStatus = "unverified-source-field" }
quests[93414] = { id = 93414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TO DEPRECATE Bloody Mercy", description = "Has Zul'jan really thrown in his lot with these snakes? I don't understand what possible reason he'd join with these monsters. What promises did they make him?\n\nZul'jan will face retribution in time. But first, these so-called Children of Ula'tek will. We'll carve a swath through them to the temple, together.", sourceObjective = "Kill the children of Ula'tek.", sourceObjectiveStatus = "unverified-source-field" }
quests[93416] = { id = 93416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: The Gulf of Memory", description = "Rumors of disturbances in the Gulf of Memory have begun to spread.\n\nDeal with the issue before it can take root.", completion = "Thank you, {name}, for nipping that in the bud.", objectives = "Complete the Gulf of Memory delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93417] = { id = 93417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vaults of Atal'Utek: Altar of Fangs", description = "Orweyna told us what she saw...\n\nDamn it, Zul'jan! Does he truly not understand what he's done? Despite what we have accomplished, he sees the bonds Zul'jarra forged with the both of us as weakness and chases this idea of a \"supreme Amani Empire\" still.\n\nAnd in the process, he has gravely wounded his sister.\n\nBut maybe Zul'jarra is right--maybe he doesn't know.\n\nWe have to get that dagger. By making him see sense, or by force.", sourceObjective = "Check on the troops inside the Vaults of Atal'Utek and complete the dungeon Altar of Fangs.", completion = "I feel a chill from within ever since we retrieved the dagger.\n\nLet's examine it, quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[93418] = { id = 93418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Venomous Abyss", description = "I saw things in de venom haze.\n\nHeard Zul'jan screamin', felt what's eatin' away at him. \n\nHeard Malacrass whisperin' in his ear.\n\nUla'tek has haunted de Amani from de beginning. De lengths we went to for power and empire, and de blood it cost...\n\nDat wasn't greatness. Deep down, Zul'jan knows it too.\n\nMalacrass stole my grandfather from me. I won't let him take Zul'jan too.", sourceObjective = "Complete the Venomous Abyss raid on any difficulty.", completion = "Zul'jarra will blame herself, but we know that she did everything--everything--to try to save him.", sourceObjectiveStatus = "unverified-source-field" }
quests[93419] = { id = 93419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nature of Her Wounds", description = "The Fang is cursed from the summoning of Ula'tek. We can use it to cure Zul'jarra. I just--\n\nWe have to act fast. She's fading!", sourceObjective = "Use the Fang of Ula'tek to heal Zul'jarra.", completion = "{name}... thank you. I saw so much. \n\n\n\nIt's too late... No!\n\n\n\nWe must find my brother.", sourceObjectiveStatus = "unverified-source-field" }
quests[93420] = { id = 93420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lor'themar's Judgement", description = "We need to tell Lor'themar what happened here. Meet me in Silvermoon.\n\nAs for Zul'jarra... she needs time. She needs her people, and her people need her.\n\nShe will survive this. I am sure of it. She must!", sourceObjective = "Return to Lor'themar Theron in Silvermoon City.", completion = "<Lor'themar regards you stiffly as you recount your efforts in Zul'Aman.>\n\nI am... glad that the Amani were able to deal with this \"Ula'tek\" on their own with your and Liadrin's help.\n\nHopefully, we hear less of them in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[93421] = { id = 93421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: The Grudge Pit", description = "<This moldy hanging has been crudely painted over to depict one fungarian hitting another with what looks to be a chair.>\n\nSee big fight. Best fight!\n\nGrudge Pit. Be there!", completion = "Good fight? Yes.\n\nBest fight? Maybe!", objectives = "Complete The Grudge Pit delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93423] = { id = 93423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: Eversong Woods", description = "Mysterious creatures are out in the wild across the Eversong Woods. \n\nGo and see what you can find out about them.", sourceObjective = "Collect 100 Sparks of War in Eversong Woods, while in War Mode.", progress = "There's still more to do.", completion = "That provides some answers, many thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[93424] = { id = 93424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: Zul'Aman", description = "There's unknown danger out in Zul'Aman.\n\nGet out there and clear things up!", objectives = "Collect 100 Sparks of War in Zul'Aman, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93425] = { id = 93425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: Harandar", description = "Powerful creatures have grown through the lands across Harandar. Go look into it.", progress = "There's more to explore.", completion = "That was a tremdenous effort - much thanks.", objectives = "Collect 100 Sparks of War in Harandar, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93426] = { id = 93426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: Voidstorm", description = "Chaotic forces are being disruptive in the Voidstorm. Go investigate and clear things up!", sourceObjective = "Collect 100 Sparks of War in Voidstorm, while in War Mode.", progress = "There's more to look out for.", completion = "This provides some answers and clarity.", sourceObjectiveStatus = "unverified-source-field" }
quests[93427] = { id = 93427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Sunkiller Sanctum", description = "<A note is pinned to the slain voidwalker.>\n\nSunkiller Sanctum is a den of Xal'atath's most pathetic sycophants.\n\nI encourage any mercenaries, adventurers, or general do-gooders who happen upon this bounty to pay it a visit and dispense the justice you are all so happy to talk on and on about.\n\n - Perodius", completion = "Your fee, {class}.\n\nThat will teach them to rebuff a perfectly good bribe in the future.", objectives = "Complete the Sunkiller Sanctum delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93428] = { id = 93428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Shadowguard Point", description = "Witness the fates of those who bend their neck to Xal'atath.\n\nI issue a challenge to any creature of Void or flesh. Pursue the nearby ethereals and dispatch anyone who serves the so-called Harbinger.\n\n - Perodius", completion = "For services rendered.\n\nIf only all mortals were as helpful as you.", objectives = "Complete the Shadowguard Point delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93432] = { id = 93432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swords to Plowshares", description = "First Mor'duun and the Blade ambush Atal'Aman. Now it's overrun by these \"echoes...\"\n\nAt least, that's what Doru calls them: echoes. All I see are ghosts of a bloodier time. And like those days, no matter how many we cut through, they never stop swarming in.\n\nGet out there and see for yourself. Bring de echoes' remains as well. Doru wants to study what dey are and how dey work.", progress = "It's like a dream you can't wake from.", completion = "See? An endless ocean.\n\nPerhaps Doru will learn something from de ashes.", objectives = "Collect 20 Raider Ash Remains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93433] = { id = 93433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine, Sealed, Delivered", description = "Curse de echoes. \n\nCurse Zul'jin, and Mor'duun, and dat snake Malacrass too.\n\nThey only cause more mess for de livin' to clean up.\n\nListen, hash'ura. I need you to deliver supplies to each of de shrines in de city. We've packaged food, water, bandages, and reagents to keep their barriers at full strength.\n\nAsk about their status as well. Though safe, they all likely feel boxed in.", completion = "Barriers holdin'? Good.\n\nNow we can focus on de offensive.", objectives = "Deliver supplies to the Elders of the four Loa Shrines: Elder Shimarra, Eagletender Rhyd, Elder Thak, and Elder Vu'lona.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93435] = { id = 93435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Instigators", description = "De scouts report seein' a few unique faces among de echoes. I felt old angers rising when I heard de names.\n\nDey were not honorable fighters for us to challenge ourselves against, such as yourself. They were vermin--greedy opportunists that drove legions of connivin' adventurers to rob us of our possessions, our treasures, and... our tusks.\n\nSlayin' de echoes of these key figures should reduce de number of echoes appearin'.\n\nAnd it will make me grin to know they've fallen.", completion = "I admit it, {name}: knowin' you have slain de instigators brings warmth to my old bones.\n\nDoes dat lower your opinion of me?", objectives = "Slay the echoes of Prigmon, Zungam, Budd Nedreck, and Harrison Jones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93436] = { id = 93436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hex the Innocent, Disrupt the Guilty", description = "I will study de ashes you acquired, but we can get dis situation under control by means other than de axe.\n\nYou must disrupt de battlefield, hash'ura. De echoes believe dey're in de midst of a decades-old battle, so we must target de support dey relied on back then.\n\nPoison de feasts dey find respite at, hex their disrespectful civilian allies, and sabotage dat chest they seem so keen on lootin'!", completion = "De echoes are runnin' from de battlefield like scared hogs because of your work!", objectives = "Poison 3 Raider's Feasts, hex 7 Civilians, and sabotage the Warlord's Chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93437] = { id = 93437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Their Own Blood", description = "After studying de ashes, Doru believes we can only fight with de past using weapons of de past.\n\nI cannot ask this of any Amani. Or Witherbark, Revantusk, or Shadowpine. Ya presence with us in these times must be fate... because we could only make this request to an outsider.\n\nYa must inhabit a soul of de profane ones: those that accepted Malacrass's vile bargain and consumed loa power during de era of Zul'jin.\n\nReturn to de shrine of de profane one ya wish to merge with.\n\nAncestors forgive us...", completion = "Thank you, hash'ura. Truly.\n\nThe battle against de echoes will continue. However, it would seem dey cannot return after being slain now dat their leader has been dealt with.\n\nMemories stirred my blood these last few days. Now we can all rest. Perhaps even move on?\n\nBah! It's just de ravin' of an old warrior. Do not mind me. \n\nSimply consider myself in your debt.", objectives = "Become one of the four Loa Avatars.\n\nSlay Raiding Echoes in Atal'Aman, and defeat the Raid Leader upon the Warlord's Stair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93438] = { id = 93438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Precision Excision" }
quests[93440] = { id = 93440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Personal History", description = "With Mor'duun slain and de Twilight's Blade defeated, my people want to return to Atal'Aman.\n\nIt should be a moment of great celebration but... somethin' unexpected is barrin' our way.\n\nSeek out Torundo and Elder Doru. Dey are supportin' de resettlement. They'll know how best to use your talents.\n\nPrepare yourself, hash'ura, and do not hesitate to defend Atal'Aman no matter who you meet there.", completion = "Zul'jarra sent you, hash'ura?\n\nHeh. She must be tired of waitin' on us to make headway.", objectives = "Speak with Torundo the Grizzled in Atal'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93449] = { id = 93449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble in the Swamp", description = "A group of my people went over to Mlurkkr Mire and have not returned. Dey were looking into an incursion of de Children of Ula'tek in de region. There are also troubling reports of de local murlocs actin' more violent than usual, and de priest Wa'kani said she detected a strong dark energy she wanted to check out.\n\nTheir leader, Zawadi, was due to report back an hour ago. Will you go find dem and lend aid if needed?", sourceObjective = "Find Zawadi in Mlurkkr Mire.", completion = "Ra'kamu sent you? Good. I could use de help.", sourceObjectiveStatus = "unverified-source-field" }
quests[93452] = { id = 93452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retrieved Crumpled Present", description = "<It seems the minions of the Greench have fled, leaving behind a small mangled, but still salvageable present.\n\nPerhaps one of the Winter Festivities planners would be able to help return it to the original intended recipient.>", sourceObjective = "Talk to Joanna Copperpinch in the Razorwind Shores neighborhood.", sourceObjectiveStatus = "unverified-source-field" }
quests[93453] = { id = 93453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grave Concern", description = "Dearly Departed,\n\nHaving just tasted the bitter sting of mortality, there seems no better time to discuss with you the oft ignored subject of death and memorialization. Of what you leave behind in a real, physical sense.\n\nLeave discussion of love and other such frivolities to the philosophers and dandies. I speak of cold, hard stone and the deeds carved upon it.\n\nFind me in Silvermoon.", progress = "Have you made your selection?", completion = "Excellent. Feel free to make new arrangements whenever you would like.\n\nI, like death, am a patient man.", objectives = "Meet with Nelthius Shadestone in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93454] = { id = 93454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words to Hear", description = "Malacrass helped my grandfather lead de Amani to ruin. Now he's gonna do de same to my brother. If we could just separate de two of them... \n\nBut Jan won't listen.\n\nHe thinks Ula'tek is a weapon dat will bring de return of de Amani Empire. After de vision he saw--and who knows what else Malacrass told him--I can't convince him otherwise.\n\nDe hash'ey requires counsel, my hash'ura. Gather de others and join me.", sourceObjective = "Advise Zul'jarra alongside your allies.", completion = "Never have the haranir's visions caused so much pain...\n\nBut knowledge in the wrong hands can be used for good or for ill.", sourceObjectiveStatus = "unverified-source-field" }
quests[93495] = { id = 93495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Soaring Journey Through Time", description = "The sands of time flow back and forth like ocean waves.\n\nJourney once more through the timeways, to the time of Dragon Aspects and Primal Incarnates.\n\nBring me tales of victory in an era of great adventure and danger.", sourceObjective = "Complete 5 Timewalking dungeons.", completion = "{name}, you've returned.\n\nWhat tales do you bring?", sourceObjectiveStatus = "unverified-source-field" }
quests[93497] = { id = 93497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Soaring Path Through Time", description = "It was a time of forging new alliances and enemies. Reminisce with me about the great Dragon Aspects and their return to glory.\n\nVenture back in time to the Dragon Isles and return with what knowledge you can.", sourceObjective = "Complete 5 Timewalking dungeons.", completion = "It's not every day one bears witness to the Dragon Aspects reforming. Cherish these moments.", sourceObjectiveStatus = "unverified-source-field" }
quests[93499] = { id = 93499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enshrouded in Arenas", description = "An important test to being a strong warrior is coordinating with others in combat. Find fellow combatants to join you in battle in the arena.", sourceObjective = "Obtain Honor in Rated Arenas while in a Party.", completion = "Very impressive - you've earned these.", sourceObjectiveStatus = "unverified-source-field" }
quests[93501] = { id = 93501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Season Starts: Midnight", description = "Things have started to get interesting, {name}. I'm hearing of all sorts of treasures popping up in delves.\n\nI'm compiling my notes in this book, and our illustrious hosts have even broken out some of their own artifacts to trade for what we uncover.\n\nWhy don't you take a look before we head out. Better prepared than dead.", sourceObjective = "Review the Delver's Guide and the rewards offered by Naleidea Rivergleam and Telemancer Astrandis.", progress = "Ready to get going?", completion = "Good. Now as long as nothing goes wrong we can get to the good part.", sourceObjectiveStatus = "unverified-source-field" }
quests[93502] = { id = 93502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enshrouded Solo", description = "Independence is key to excel in battle. Display your solo capabilities in then come back to me.", sourceObjective = "Complete 12 rounds of Solo Shuffle.", completion = "Great work, soldier. Take these.", sourceObjectiveStatus = "unverified-source-field" }
quests[93503] = { id = 93503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enshrouded in Teamwork", description = "The ability to work with a group to take objectives is key in training. Practice this on the battlefield.", sourceObjective = "Obtain Honor in Rated Battleground Blitz or in Rated Battlegrounds.", completion = "Great work! You have earned these.", sourceObjectiveStatus = "unverified-source-field" }
quests[93504] = { id = 93504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enshrouded in Skirmishes", description = "Practice makers perfect. A great place to practice is with others like yourself looking to practice. Set off and find others like yourself to practice small-scale skirmishes, then return to me.", sourceObjective = "Obtain Honor from Arena Skirmishes.", completion = "Great practice! You've earned this!", sourceObjectiveStatus = "unverified-source-field" }
quests[93505] = { id = 93505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enshrouded in War", description = "Large conflicts get you to take a look at the larger picture. Give it a try then come back to me.", sourceObjective = "Obtain Honor in Epic Battlegrounds.", completion = "Great effort.. Here, take this.", sourceObjectiveStatus = "unverified-source-field" }
quests[93506] = { id = 93506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enshrouded in Battle", description = "You can learn a lot on the battlefield on your own. Go ahead and see what you observe.", sourceObjective = "Obtain Honor in Random Battlegrounds.", progress = "There's still more to explore.", completion = "It pays off to have an open mind! Take this for your time.", sourceObjectiveStatus = "unverified-source-field" }
quests[93507] = { id = 93507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupting the Void" }
quests[93511] = { id = 93511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Missing Member", description = "He took him! Finley...big...purple...man!\n\n<Reno is clearly distraught and both physically and emotionally exhausted.>", sourceObjective = "Listen to what Reno has to say.", progress = "He looks devastated.", completion = "Kidnapping a murloc? For shame.", sourceObjectiveStatus = "unverified-source-field" }
quests[93514] = { id = 93514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of the Singularity" }
quests[93517] = { id = 93517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otherworldly Intelligence" }
quests[93519] = { id = 93519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight Delves!", description = "Things are starting to get interesting in Delves.\n\nCome see me in Silvermoon.", sourceObjective = "Visit Valeera in Silvermoon.", completion = "We've got a lot to discuss.", sourceObjectiveStatus = "unverified-source-field" }
quests[93520] = { id = 93520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - 12.x Midnight - Raid Finder - Nth" }
