quests[93524] = { id = 93524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trench Run" }
quests[93525] = { id = 93525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nulling Nullaeus", description = "That thing looked tough, and it took Reno out as an afterthought.\n\nWe'll want the best gear we can get before trying to take it down.\n\nThankfully, I have some leads on bountiful delves we can start with.", sourceObjective = "Improve your gear until you are able to confront Nullaeus within his lair.", progress = "He'll get what's coming to him.", completion = "Thanks for the assist.\n\nI've been where Finley was.", sourceObjectiveStatus = "unverified-source-field" }
quests[93548] = { id = 93548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trove of Voidlight Marl" }
quests[93549] = { id = 93549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cluster of Voidlight Marl" }
quests[93566] = { id = 93566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Amani Tribe", description = "You continue to prove yourself to de Amani and de other forest tribes alike.\n\nSpeak to me when next you are in Amani'Zar. Zul'jarra asked me to put a few items aside as our way of sayin' thanks.", sourceObjective = "Speak with Magovu in Amani'Zar Village.", sourceObjectiveStatus = "unverified-source-field" }
quests[93569] = { id = 93569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exaliburn" }
quests[93571] = { id = 93571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dispersing Shadows" }
quests[93573] = { id = 93573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deciphering Darkness" }
quests[93575] = { id = 93575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maisara Caverns: Maisara Hungers", description = "I will not leave my people to die to de Vilebranch's dark rituals. We must go after dem.\n\nThe heart of Maisara Caverns is where de Vilebranch keep their secrets. I expect dis to be a bloody trip. We will have to face de ugliness of the Vilebranch greed, and what it is costin' all of us.\n\nWe must discover what purpose they have for my stolen kin. If any still be alive. I will be dere to aid you... but bring a fierce party of warriors. We will need it.", progress = "Gather your warparty. I will see you in Maisara Caverns.", completion = "Dat be a dark business indeed. So many lost, to such a terrible fate!\n\nBut no more, thanks to you. You have de Witherbark's gratitude... and mine.", objectives = "Complete the Maisara Caverns dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93576] = { id = 93576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search for Wa'kani", description = "While you were keepin' de snakes busy, I was lookin' for Wa'kani and de other scouts. De scouts are still missin', but Wa'kani is in dat temple over there.\n\nI tried gettin' closer, but it's too heavily guarded. You should have no problem, though. Please rescue my fool sista before de snakes do something foul to her.", sourceObjective = "Free Wa'kani.", completion = "Thank you for freein' me. We can't leave yet, though. I found de source of all these eggs!", sourceObjectiveStatus = "unverified-source-field" }
quests[93577] = { id = 93577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captured Instinct" }
quests[93578] = { id = 93578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Shadows Gather" }
quests[93579] = { id = 93579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Purgation" }
quests[93581] = { id = 93581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "Slay 25 Level 90 Horde anywhere within Midnight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93582] = { id = 93582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "Slay 25 Level 90 Alliance anywhere within Midnight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93586] = { id = 93586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional - Multiple Objectives, Non Sequenced", description = "I be sent out here ta prove dat I can be an amani warrior.\n\nDis trial needs me ta collect as many trophies from dese gnarldin as possible. \n\nDe two of us should work together! I be helpin' you get recognized as an amani warrior, yeah?\n\nJust go out dere and get as many trophies from de gnarldin as possible. \n\nI be stayin' behind ta watch our backs, eh?", objectives = "Recover 1 trophies from gnarldin and their allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93593] = { id = 93593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Battle", description = "Ours is a world of constant struggle, wouldn't you agree? Even in between times of peace, there is value in keeping one's battle skills sharpened.\n\nI have heard much of your prowess. Let us see what you are capable of.", sourceObjective = "Win 4 Battleground matches.", progress = "There is no substitute for constant vigilance, {class}. Al'anna, dalomore.", completion = "How did you fare in the battlegrounds? Some wins? Some losses?\n\nThere are lessons to be learned from both.", sourceObjectiveStatus = "unverified-source-field" }
quests[93595] = { id = 93595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Delves", description = "Seeking out challenge and treasure can test one's skills, all while uncovering that which will give us even greater power.\n\nWere I you, I would delve into places that provide both.", sourceObjective = "Complete 5 Midnight Delves.", progress = "Has your delving come to a satisfactory conclusion?", completion = "You yet live, which means two things. The first is that I was correct in guiding you to those delves. The second is that you are more capable than you were before.", sourceObjectiveStatus = "unverified-source-field" }
quests[93598] = { id = 93598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of War", description = "It is only when we push ourselves beyond our limits that we truly grow... or fail and make way for others.\n\nProve yourself by challenging the deadliest of places. Shorel'aran.", sourceObjective = "Complete 4 dungeons on Mythic difficulty.", progress = "Will you become the stuff of myths and legends, {class}?", completion = "You have proven yourself beyond even my wildest expectations. Well done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[93599] = { id = 93599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Very Best", description = "Even the smallest amongst us must play their part. That includes our little friends.\n\nIf you would strengthen both their prowess and your bond, challenge others. Only the fittest will survive.You will be able to choose one of these rewards:", objectives = "Defeat 5 players through Find Battle with a team of level 25 pets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93600] = { id = 93600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arena Calls", description = "Old, musty dungeons and battlefields are one thing, but the arena is where the wheat and the chaff are separated.\n\nCan you prove yourself, {class}? Show me. Let me hear your name shouted from the stands by those crying for blood.", sourceObjective = "Win 10 Arena Skirmish battles.", completion = "Impressive. But remember, a champion only remains so as long as they continue to win.", sourceObjectiveStatus = "unverified-source-field" }
quests[93605] = { id = 93605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The World Awaits", description = "Sinu a'manore, {class}. It is true in the past, I have been less than... egalitarian in my outlook. Yet in these times of trouble, there is much to be done--whether here in Quel'Thalas or elsewhere.\n\nWill you face the challenge and prove yourself once more?", sourceObjective = "Complete 10 Midnight World Quests.", progress = "Trouble is everywhere. We are measured by how we overcome these obstacles.\n\nWill it be with grace or fury? Perhaps a bit of both?", completion = "Your efforts are known and appreciated. Anu bala belore'alon.", sourceObjectiveStatus = "unverified-source-field" }
quests[93607] = { id = 93607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Original Path Through Time", description = "Greetings, {class}. You come to me because you seek answers. I have nothing for you but guidance.\n\nPerhaps the answers you seek lie in the past? Return to that time mere years after the conclusion of the Third War. Face its threats once again and see what wisdom you can glean.", sourceObjective = "Complete 5 Timewalking dungeons.", completion = "Be sure to share anything you may have learned from the past so that we do not make the same mistakes in the future.\n\nAl diel shala, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[93608] = { id = 93608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Burning Path Through Time", description = "On the other side of the Dark Portal lies Outland. I've never been--my history is tied to the Kirin Tor rather than Silvermoon. Yet the elves of Quel'Thalas went through much turmoil during that period of time. \n\nPerhaps you could learn a thing or two from that fractured world. Take up the challenge, if you feel worthy of it.", sourceObjective = "Defeat 5 Timewalking raid bosses or dungeons.", completion = "The elves of Quel'Thalas suffered much during that period of time--but learned more truths and lessons than can be truly counted. \n\nNo doubt you are stronger and wiser for the journey you have taken.", sourceObjectiveStatus = "unverified-source-field" }
quests[93610] = { id = 93610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Frozen Path Through Time", description = "The lessons of the past must be revisited from time to time and brought back to the present as a reminder.\n\nWalk the timeways and return to when the Lich King and the armies of the Scourge emerged from the icy wastes of Northrend and threatened all of Azeroth. There is much to be learned from that time.", sourceObjective = "Defeat 5 Timewalking raid bosses or dungeons.", completion = "May the lessons you have learned be helpful, if grim. And may those who fell during those days know peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[93611] = { id = 93611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shattered Path Through Time", description = "The Cataclysm was terrifying for all of Azeroth. The existential threat of Deathwing echoes down through the ages. Isn't it interesting that no matter how things change, such threats return time and time again, but in different forms?\n\nGo back and face those threats again. See if there's something new to learn from the past.", sourceObjective = "Defeat 5 Timewalking raid bosses or dungeons.", progress = "I... would not relive those times. Some memories are best left behind.", completion = "You have more courage than I, champion. Let us hope any lessons you have learned will be carried forward in earnest.", sourceObjectiveStatus = "unverified-source-field" }
quests[93612] = { id = 93612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shrouded Path Through Time", description = "My memories of Pandaria are... complicated, {class}. Many lessons were learned during that tumultuous period of time--some good, some painful. \n\nThe world has changed a great deal since then. We've all changed--I hope for the better.\n\nTravel back through the mists of time. Relearn what lessons you can.", sourceObjective = "Complete 5 Timewalking dungeons.", completion = "Have you returned enlightened or embittered by the decisions of the past? I hope your lessons were easier to learn than my own.", sourceObjectiveStatus = "unverified-source-field" }
quests[93613] = { id = 93613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Savage Path Through Time", description = "Perhaps you can untangle the depth of knowledge to be found in Draenor--not the shattered remains of Outland, but the Draenor of the Iron Horde. It is, in its own ways, just as harsh if not harsher than Outland ever was. \n\nSee what wisdom you can find there.", sourceObjective = "Complete 5 Timewalking dungeons.", completion = "Well done, {class}. It's intriguing to consider what might have been, and view the splintering of history with one's own eyes. I hope it was an illuminating journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[93614] = { id = 93614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fel Path Through Time", description = "I have faced many enemies, but the Burning Legion was perhaps the greatest threat our world ever faced. At least... until now.\n\nOf course, there are our inner demons to contend with as well.\n\nDo you still have what it takes to defeat the Burning Legion?", sourceObjective = "Complete 5 Timewalking dungeons.", completion = "You do indeed still have what it takes. May the Legion never return.", sourceObjectiveStatus = "unverified-source-field" }
quests[93627] = { id = 93627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scarred Path Through Time", description = "I remember well the battles of the Alliance and Horde that played out in Kul Tiras and Zandalar. Return there, relive the memories. \n\nWill you seek glory, or knowledge? Or perhaps both?", sourceObjective = "Complete 5 Timewalking dungeons.", completion = "Returned at last--with victory under your belt, or perhaps deeper lessons learned than what can be found in the throes of battle?", sourceObjectiveStatus = "unverified-source-field" }
quests[93628] = { id = 93628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shadowed Path Through Time", description = "Would you return to the realm of death and risk your very existence? Rebirth, eternal peace, endless torment? All can be found across the veil. \n\nTravel to the Shadowlands once more. If you can defeat its most dangerous places, perhaps you will return to the living wiser and more powerful.", sourceObjective = "Complete 5 Timewalking dungeons.", completion = "To stride boldly into the lands of the afterlife and come out the other side... a Maw Walker indeed, every inch of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[93640] = { id = 93640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Finagling", description = "I had wanted to bring the tea set home to my wife to surprise her...\n\nBut that won't make up for me not bringing home any fish for supper.\n\nHm. I'll make a deal with you, {class}. I've been standing here all day trying to catch some fish for my beautiful wife to cook for us. But the crabs keep stealing my catch--and my bait! Run them off so I can catch and keep some fish, and I will give you this teapot." }
quests[93641] = { id = 93641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "Slay 25 Level 90 Horde anywhere within Midnight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93642] = { id = 93642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "Slay 25 Level 90 Alliance anywhere within Midnight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93647] = { id = 93647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumber For You", objectives = "Ye look like someone who could learn the art of bein' a lumberjack!\n\nI can teach ye real quick how to identify which trees are prime for gettin' some lumber.\n\nLumber has all sorts of uses when crafting stuff for yer house. Or other folks' houses, if you care to sell your goods. Might want to visit some o' your old craftin' teachers to brush up while you're at it. They've got some new things to teach, I'd wager!\n\nSo get what ye can and see what ye can make of it!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93648] = { id = 93648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnarly Skullduggery" }
quests[93649] = { id = 93649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Got the Gall" }
quests[93651] = { id = 93651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blinding Vale: Lightbloom Roots", description = "We have traced Ruia's flight through the Rootways. As we suspected, he has sought refuge deep within The Blinding Vale, where the Lightbloom first took root within Harandar.\n\nWith Alndust empowering our command of life, we are able to keep the Lightbloom from spreading uncontrolled. But we will run out of Alndust long before Ruia runs out of patience.\n\nRuia is wise and powerful. But his actions in Eversong prove that his conviction has grown into an uncontrollable fanaticism. He must be stopped.", completion = "So it is done, then.\n\nRuia's demise is a tragedy. You never knew him as such, but he was once a man of honor and conviction. To think that the Light would blind him so completely to the folly of his ambitions...\n\nIn the end, he thought he was doing what was best for Harandar. I can only hope his soul finds both peace and forgiveness, as it seeks Aln'hara in death.", objectives = "Complete The Blinding Vale dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93664] = { id = 93664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotten Fish" }
quests[93667] = { id = 93667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camp Stonewash", description = "You're not the first strange thing I've seen today.\n\n<Scout Zel'kanra shakes her head.>\n\nSaw a big, shelled creature along the path to Jan'Alor. Amaxi took a bunch of scouts and went after it.\n\nThey've been gone a while. Think you could check in on them?", completion = "Who are you? What are you doing here?\n\n<Amaxi tenses, but relaxes after a moment.>\n\nShadebasin sent you. Yes, we're fine. But these tortollan should not be here!", objectives = "Find Amaxi outside Camp Stonewash in Zul'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93668] = { id = 93668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old Game for a New Age", description = "Greetings, {class}. Have you heard of my joint venture with Aethas Sunreaver and Auric Sunchaser? We have been attempting to rekindle interest in an old arcane tournament of stealth versus perception, called Decor Duel.\n\nWe're currently training new players, so if you'd like to learn the ropes of the game, feel free to meet us in the Decor Duel training area, just west of here.", sourceObjective = "Meet up with Aethas Sunreaver, Riftblade Maella, and Auric Sunchaser at the Decor Duel training area.", sourceObjectiveStatus = "unverified-source-field" }
quests[93669] = { id = 93669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curse of Greed" }
quests[93670] = { id = 93670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How 'Bout Them Apples?" }
quests[93671] = { id = 93671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tight Squeeze" }
quests[93672] = { id = 93672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blade to Rest" }
quests[93683] = { id = 93683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional Objectives - Singular", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly disrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93687] = { id = 93687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taste True Power", objectives = "This quest line will unlock:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93690] = { id = 93690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alchemy Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", progress = "Bring back proof of completed orders and I'll see that you're adequately compensated.", completion = "You have our gratitude, {class}. Silvermoon stands stronger thanks to your skills.", objectives = "Fill Alchemy Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93691] = { id = 93691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blacksmithing Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", progress = "Bring back proof of completed orders and I'll see that you're adequately compensate", completion = "You have our gratitude, {class}. Silvermoon stands stronger thanks to your skills.", objectives = "Fill Blacksmithing Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93692] = { id = 93692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Engineering Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", completion = "You have our gratitude, {class}. Silvermoon stands stronger thanks to your skills.", objectives = "Fill Engineering Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93693] = { id = 93693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inscription Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", completion = "You have our gratitude, {class}. Silvermoon stands stronger thanks to your skills.", objectives = "Fill Inscription Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93694] = { id = 93694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jewelcrafting Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", progress = "Bring back proof of completed orders and I'll see that you're adequately compensated.", completion = "You have our gratitude, {class}. Silvermoon stands stronger thanks to your skills.", objectives = "Fill Jewelcrafting Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93695] = { id = 93695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leatherworking Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", completion = "You have our gratitude, {class}. Silvermoon stands stronger thanks to your skills.", objectives = "Fill Leatherworking Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93696] = { id = 93696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tailoring Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", progress = "Bring back proof of completed orders and I'll see that you're adequately compensated.", completion = "You have our gratitude, {class}. Silvermoon stands stronger thanks to your skills.", objectives = "Fill Tailoring Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93697] = { id = 93697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shimmering Melodies", description = "Have you heard it? The magic of Eversong. It emanates a subtle melody, if you listen closely enough. The complex interwoven strands of magic move against each other and create a beautiful harmony.\n\nThe dust distilled from such magic is exceptionally potent. Bring some to me and I will show you its uses.", sourceObjective = "Collect 20 Eversinging Dust and deliver it to Dolothos in Silvermoon.", progress = "Have you collected the dust?", completion = "This dust is of exceptional quality! Come, I will show you some techniques that make use of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[93698] = { id = 93698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splintered Radiance", description = "When captured at just the right moment, the power exuding from an object can be crystallized into splinters of raw magical energy. The result is dazzling, like beams of sunlight splitting as they stream through a window.\n\nBring me some of these shards. My work cannot continue without them.", progress = "A few shards should be sufficient.", completion = "Oh, they glow with such wonderful power! These should do nicely.", objectives = "Collect 10 Radiant Shards and deliver it to Dolothos in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93699] = { id = 93699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ray of Sunlight", description = "There is great magic in the dawn. It illuminates and awakens all it falls upon, rousing the land to action. It is potential in its purest form.\n\nAs enchanters, we can crystallize that potential. Bring a parcel of the dawn to me.", objectives = "Collect 1 Dawn Crystal and deliver it to Dolothos in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93700] = { id = 93700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Experience Tranquility", description = "Are you an herbalist? Oh, thank goodness.\n\nI've found myself in need of an exorbitant amount of tranquility bloom. The orders from the alchemists keep piling up and I only just finished restocking our argentleaf and--\n\n<Nathera stops to take a deep breath.>\n\nCould you please bring me as much tranquility bloom as you can carry? I'd be in your debt.", sourceObjective = "Collect 20 Tranquility Bloom and deliver it to Botanist Nathera in Silvermoon.", progress = "Have you found any tranquility bloom?", completion = "Bless you. This will give me some extra time to catch up on orders.", sourceObjectiveStatus = "unverified-source-field" }
quests[93701] = { id = 93701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brittle and Brilliant", description = "Argentleaf is always in high demand whenever war draws near.\n\nIt practically falls apart when you dry it out, but that powder can be used in a variety of medicines. It calms the nerves, focuses the mind, and can even work as a mild anesthetic in a pinch.\n\nIf you find any out in the field, please bring it to me.", sourceObjective = "Collect 20 Argentleaf and deliver it to Botanist Nathera in Silvermoon.", progress = "Argentleaf grows like a weed, to be honest. You should find plenty.", completion = "I'll get these bundles hung up to dry at once. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[93702] = { id = 93702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Root of Life", description = "Most tuberous roots have some sort of healing potential, but azeroot is by far the most potent and versatile.\n\nJust a small amount, juiced or powdered, can stave off infections, promote healing, and soothe both body and mind. I've even seen it used to keep lumber from rotting!\n\nIf you could bring me a few bushels, I'll put it to good use.", sourceObjective = "Collect 3 Azeroot and deliver it to Botanist Nathera in Silvermoon.", progress = "Were you able to track down any azeroot?", completion = "Oh, I love the scent of fresh azeroot. Perhaps I should see how it would do in a perfume...", sourceObjectiveStatus = "unverified-source-field" }
quests[93703] = { id = 93703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sin'dorei Vices", description = "While most of our harvests supply the scribes and alchemists in the city, we do occasionally receive orders from the public.\n\nLord Saltheril is one of our most prolific customers. He has an estate in western Eversong that he keeps well-supplied with offerings for guests at his soirees.\n\nHe has requested a large quantity of mana lilies and sanguithorn this week. Could you help us fulfill the order?", progress = "Lord Saltheril's business is always welcome, even if a bit eccentric.", completion = "Excellent. With your help and what we already have in stock, this should cover his order.", objectives = "Collect 5 Mana Lilies and 2 Sanguithorn and deliver it to Botanist Nathera in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93704] = { id = 93704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traditional Harvests", description = "Tranquility bloom and argentleaf are the backbone of countless potions, elixirs, inks, and so much more.\n\nIt never hurts to keep a surplus around. If you find yourself with any extra, we would gladly take it off your hands.", sourceObjective = "Collect 10 Tranquility Blooms and 5 Argentleaf and deliver it to Botanist Nathera in Silvermoon.", progress = "We'll take whatever you can offer.", completion = "Sometimes a simple blend is the best blend. No shame in sticking to the basics.", sourceObjectiveStatus = "unverified-source-field" }
quests[93705] = { id = 93705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Copper for Your Thoughts?", description = "It's easy to overlook in favor of more extravagant materials, but copper is an extremely reliable and versatile material. Weapons, armor, wiring, jewelry, and of course the humble copper coin--it does it all!\n\nNaturally, copper is always in high demand across the city and beyond. If you happen across any extra ore, I would gladly take it off your hands.", sourceObjective = "Collect 20 Refulgent Copper Ore and deliver it to Belil in Silvermoon.", progress = "You know, I wrote my thesis on the uses of copper. Have you read it?", completion = "This is even more than I expected! Wonderful. I'll see this put to use immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[93706] = { id = 93706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Tin-dencies", description = "There's been an influx of newly recruited soldiers lately. Marvelous fighters in the making, but a little too enthusiastic. They've already done a number on the stock of training weapons.\n\nWe usually make training weapons out of tin or other soft metals. They keep the recruits from doing real damage to the training dummies or each other, but they don't last long.\n\nWe'll need a lot more tin than what we have in stock to keep up. Bring us some more!", objectives = "Collect 10 Umbral Tin Ore and deliver it to Belil in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93707] = { id = 93707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Called Silvermoon", description = "Elegant gold filigree may be a favorite of the sin'dorei, but our city also boasts some of the finest silversmiths in Azeroth.\n\nThey have been receiving a particularly high number of orders with all of the new visitors passing through. If you come across any high-quality silver, they can put it to good use.", sourceObjective = "Collect 10 Brilliant Silver Ore and deliver it to Belil in Silvermoon.", progress = "I have a certain fondness for silver myself, truth be told.", completion = "What remarkable quality! I'll have this shipped over to the jewelers at once. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[93708] = { id = 93708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conductive Metals", description = "Our arcane constructs might look purely magical, but there's quite a bit of advanced wiring going on beneath the surface. Silvermoon's engineers truly are spell-workers in their own right.\n\nThey've been ramping up production lately to help fortify our defenses. Naturally, they look to us for supplies. I have most of the materials they ordered, but I'm low on tin and silver.\n\nCould you help me fulfill the order?", progress = "Tin and silver are both remarkably conductive. I could elaborate, if you have a few hours?", completion = "Ah, yes. This quantity should be sufficient. I'll have it packaged up for the engineers.", objectives = "Collect 5 Umbral Tin Ore and 5 Brilliant Silver Ore and deliver it to Belil in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93709] = { id = 93709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stocking the Staples", description = "One can never have too much copper and thorium on hand. Even with all the new miners we brought on, we still nearly deplete our stocks every week.\n\nAt this rate, we'll have to start importing--and I do not want the headache that sort of paperwork brings.\n\nIf you could help us replenish our stock of copper and thorium, I would be in your debt.", sourceObjective = "Collect 10 Refulgent Copper Ore and 2 Dazzling Thorium and deliver it to Belil in Silvermoon.", progress = "I suppose I could bring on a few more apprentices, if I have to...", completion = "You are one of the most reliable miners I've ever had the pleasure of meeting.\n\nThank you. Truly.", sourceObjectiveStatus = "unverified-source-field" }
quests[93710] = { id = 93710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempered in Darkness", description = "The beasts of Quel'Thalas produce leather of unparalleled quality, but the Void has been doing something strange to it.\n\nNormally, we harden leather by heating it under specific conditions. But the darkness clinging to these hides seems to be tempering the leather on its own. I have no idea how this is possible, but we can make use of it.\n\nBring me as much as you can gather. We have an army to supply.", sourceObjective = "Collect 20 Void-Tempered Leather and deliver it to Tyn in Silvermoon.", progress = "We'll find a use for any leather you can bring us.", completion = "What strange properties... I'll keep a sample for study. In the meantime, this leather will make fine armor for our Farstriders.", sourceObjectiveStatus = "unverified-source-field" }
quests[93711] = { id = 93711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chill of the Void", description = "When we mobilized troops to Northrend many years ago, we had to outfit our soldiers to withstand the icy chill of the frozen wastes. The secret is lining the inside of the armor with fur and plating it securely to trap warmth inside.\n\nWe kept detailed records of those techniques. The Void may not be as cold as Northrend, but I'd rather be prepared for the worst.\n\nBring me a supply of fur and plating and I'll see you compensated.", sourceObjective = "Collect 5 Fantastic Fur and 2 Void-Tempered Plating and deliver it to Tyn in Silvermoon.", progress = "As an added benefit, the fur prevents quite a bit of chafing.", completion = "Our leatherworkers should be able to use these materials. Nicely done.", sourceObjectiveStatus = "unverified-source-field" }
quests[93712] = { id = 93712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Style and Skill", description = "In battle, appearances are nearly as important as raw skill. If you can intimidate your foe before you've even drawn your sword, you're already that much closer to victory.\n\nOur fletchers take this a step further and insist that beautiful feathers make our Farstriders' arrows do more damage. I'm... not certain about that, but I can appreciate the aesthetic.\n\nHere's a list of what they need for this week's batch of arrows. Supply whatever you can and I'll handle the rest.", progress = "You can ignore the note about whether the feathers should be crimson or scarlet.", completion = "Ah, these should make excellent arrows.", objectives = "Collect 5 Carving Canines and 5 Peerless Plumage and deliver it to Tyn in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93713] = { id = 93713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essential Materials", description = "The Horde's penchant for teeth and animal pelts has worn off on some sin'dorei. It's not uncommon in recent years to receive bulk orders for both.\n\nThis is one of those times. If you have any spare hides, or come across any particularly sharp teeth in your hunts, I'd gladly trade you for them.", sourceObjective = "Collect 5 Carving Canines and 2 Void-Tempered Hides and deliver it to Tyn in Silvermoon.", progress = "I'll never understand orcish fashion.", completion = "Well, this should be enough to cover the most recent order. I'll try to restock in preparation for the next one.\n\nPleasure working with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[93714] = { id = 93714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minor Scales", description = "A well-made suit of scalemail is a sight to behold. It requires quite a bit of patience and attention to fine detail, but Silvermoon's leatherworkers are masters of the craft.\n\nIf you happen to hunt any scaled beasts, we could use those materials. A large quantity of smaller sized ones, if you could--they layer more nicely in the armor.", objectives = "Collect 20 Void-Tempered Scales and deliver it to Tyn in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93716] = { id = 93716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Cloaks - Part 1", description = "In this game of Decor Duel, one side uses illusion to disguise themselves as, and hide amongst, everyday objects in the area.\n\nThe other side uses pre-approved lists of illusion-piercing abilities to find and then capture those hiding cloaked in disguise.\n\nAt the end of the round, the teams switch roles, so each side has a chance to hide and seek. \n\nTime for you to try! This armchair has been enchanted to cloak you with its disguise. Don its appearance, then change your disguise a few times.", sourceObjective = "Interact with the armchair to become disguised, then use its Disguise ability a few times, then speak with Captain Auric Sunchaser.", progress = "Touch this armchair, to don its disguise...", completion = "You took to that like a cloak to concealment. Well done!\n\nBut, in this game, a good disguise or hiding spot isn't always enough. There is much more for you to learn.", sourceObjectiveStatus = "unverified-source-field" }
quests[93717] = { id = 93717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Cloaks - Part 2", description = "When disguised, you will have the ability to magically teleport yourself to a nearby piece of decor.\n\nPick up the chair's disguise again, and this time try swapping your location a few times. Feel free to change your disguise between swaps if you'd like.", sourceObjective = "Pick up the Chair's disguise to test out its Swap ability, then speak with Aethas Sunreaver.", progress = "Use the disguise chair to swap with other decor, then return to me.", completion = "Nicely done! But that's only half the game, isn't it.\n\nNext, let's get you exposed to some Capturing tactics. If you think you can handle it, of course.", sourceObjectiveStatus = "unverified-source-field" }
quests[93719] = { id = 93719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing Captured, Nothing Gained", description = "There are three Seeker classes in Decor Duel, but everyone starts off with the Spellbreaker kit. Don't worry--you can earn access to the others.\n\nSome fundamentals: you can break the shield of a disguised hider's illusion by using Dispel Magic. Once the hider has been marked as Found, you'll have a brief window to Tag them, taking them out of the match.\n\nMy statue has been enchanted to outfit you with a Spellbreaker kit. Once outfitted, use Dispel Magic to find and tag decoys hiding around here.", sourceObjective = "Interact with the statue to become outfitted with a Spellbreaker Kit, use the Dispelling Focus to \"Find\" hiders, then \"Tag\" them.", progress = "Use my statue, then find and tag hiders with the Spellbreaker's Dispel Magic and Tag.", completion = "Not bad for a first time. You're taking to this quite naturally!", sourceObjectiveStatus = "unverified-source-field" }
quests[93723] = { id = 93723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafters Needed", description = "Greetings. Come to lend a hand?\n\nThe war effort has been taxing on Silvermoon's resources. We need to keep our soldiers armed and supplied, but even our seasoned crafters have been overwhelmed. To keep up with demand, we have struck a deal with the Artisan's Consortium.\n\nIf you have your own skills to offer, speak to Mar'nah. She can help you view and place crafting orders.", progress = "Have you talked to Mar'nah?", completion = "Fulfilling these work orders is imperative to the war effort. Your services are greatly appreciated.", objectives = "Talk to Mar'nah in the Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93724] = { id = 93724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Orders: Alchemy", description = "Ah, you're an alchemist?\n\nYou should speak with Camberon. He's a skilled alchemist who runs a shop here in Silvermoon.\n\nCamberon has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek him out and see what work is available for you.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "It is ever an honor to meet a fellow alchemist. Clean up your spills and we'll be well on our way to friendship.", objectives = "Find Camberon in the Bazaar and use his Alchemist's Lab Bench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93726] = { id = 93726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Orders: Blacksmithing", description = "Ah, you're a blacksmith?\n\nYou should speak with Bemarrin. He's a skilled blacksmith who runs a shop here in Silvermoon.\n\nBemarrin has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek him out and see what work is available for you.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "A pleasure meeting you. But if you misplace my good pair of tongs, I'll have you thrown right out.", objectives = "Find Bemarrin in the Bazaar and use his Blacksmith's Table.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93727] = { id = 93727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Orders: Engineering", description = "Ah, you're an engineer?\n\nYou should speak with Danwe. She's a skilled engineer who runs a shop here in Silvermoon.\n\nDanwe has a work table at her shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek her out and see what work is available for you.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "Good engineers are hard to come by. Get a handle on those arcane constructs and you'll be drowning in work from the Magisters alone.", objectives = "Find Danwe in the Bazaar and use her Tinker's Workbench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93728] = { id = 93728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Orders: Inscription", description = "Ah, you're a scribe?\n\nYou should speak with Zantasia. She's a skilled scribe who runs a shop here in Silvermoon.\n\nZantasia has a work table at her shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek her out and see what work is available for you.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "You have a fine and steady hand, {name}. I look forward to seeing what you can create.", objectives = "Find Zantasia in the Bazaar and use her Scribe's Drafting Table.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93729] = { id = 93729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Orders: Jewelcrafting", description = "Ah, you're a jewelcrafter?\n\nYou should speak with Amin. He's a skilled alchemist who runs a shop here in Silvermoon.\n\nAmin has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek him out and see what work is available for you.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "It seems like every set of armor these days needs a dozen gems inlaid. Not that I am complaining, especially not with your aid whittling down the work orders.", objectives = "Find Amin in the Bazaar and use his Jeweler's Bench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93730] = { id = 93730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Orders: Tailoring", description = "Ah, you're a tailor?\n\nYou should speak with Galana. She's a skilled tailor who runs a shop here in Silvermoon.\n\nGalana has a work table at her shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek her out and see what work is available for you.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "Fine spellcasters demand fine robes, but their high standards keep our skills sharp. Perhaps you and I can share techniques.", objectives = "Find Galana in the Bazaar and use her Tailor's Work Table.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93731] = { id = 93731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Orders: Leatherworking", description = "Ah, you're a leatherworker?\n\nYou should speak with Talmar. He's a skilled leatherworker who runs a shop here in Silvermoon.\n\nTalmar has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek him out and see what work is available for you.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "The beasts of Quel'thalas have the finest leather you will ever work with. I look forward to seeing what you make of it.", objectives = "Find Talmar in the Bazaar and use his Leatherworker's Tool Bench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93734] = { id = 93734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Trinkets", description = "Finally we get to see what treasures Groffa was hoarding.\n\n<Furgh's eyes go black as he looks at the bag. The drool on his jowls turns to foam and his claws dig into the sides of the bag as his grip on it tightens.>\n\nMaybe the loa speaker's gifts aren't so bad. We should not be so hasty. I'll take a look. You watch and keep me safe.", progress = "Whatever Groffa had is bad. Right?", completion = "You didn't need to burn my things...", objectives = "Keep Furgh safe and investigate the treasures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93744] = { id = 93744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unity Against the Void" }
quests[93745] = { id = 93745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Har'athir, Village of Memory", description = "You have been permitted to range about beneath our Goddess' light. But that doesn't mean we trust you out of hand.\n\nIf you wish to prove yourself a friend to the haranir, make yourself useful in Har'athir. It is there that we make the paints for our murals and watch over the newest roots to seek the Goddess' light.", completion = "So you survived your meeting with the elders. I am surprised, but also pleased.\n\nYou aided the children of Har'athir without hesitation. For that, I welcome you and offer you the hospitality of Amirdrassil's roots.", objectives = "Meet Rootwarden Ku'paal in Har'athir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93751] = { id = 93751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windrunner Spire", description = "Former home of the Windrunners... now desecrated beyond thought. Since the Scourge invasion, the spire houses our greatest nightmares: banshees, abominations, hateful spirits.\n\nThere is no redeeming such a place, but perhaps we may help lay the tormented to rest.", sourceObjective = "Complete the Windrunner Spire dungeon on any difficulty.", completion = "It's as I thought... the spire houses more than just remnants of the Scourge. It's a mirror to the tragedies that befell the Windrunner family.", sourceObjectiveStatus = "unverified-source-field" }
quests[93752] = { id = 93752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder Row", description = "I've always disagreed with Lor'themar about the existence of Murder Row. But I guess like any forest, a city should and will have its secrets.\n\nThough recently, Lor'themar has expressed concern about rising fel activity in the area. With the majority of Silvermoon's watch on the Voidstorm, many folks are testing boundaries, taking advantage, making a play for power...\n\nYou have my permission to investigate and crush any such illegal activities.", sourceObjective = "Complete the Murder Row dungeon on any difficulty.", sourceObjectiveStatus = "unverified-source-field" }
quests[93753] = { id = 93753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magisters' Terrace", description = "Powerful monsters of the void have taken over Magister's Terrace! These halls contain untold amounts of knowledge and arcane power. We cannot lose any of it to our enemy.\n\nClear the voidspawns and their masters. You'll likely have to solve the terrace's defenses as well, which are designed to prevent and shutdown unauthorized access at any cost.", progress = "If the Void gains access to Silvermoon's most exclusive repository of magic... Rommath will throw a fit of epic proportions.", completion = "That was a close call. As for Rommath and Umbric, that's a puzzle for another day.", objectives = "Complete the Magisters' Terrace dungeon on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93754] = { id = 93754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maisara Caverns", description = "While Lady Liadrin was in Zul'Aman, she took note of one tribe, the Vilebranch, brutalizing the other forest trolls and their loa. They live up to their name by wanton use of necromancy.\n\nEnter their caverns and put a stop to their black magic!", sourceObjective = "Complete the Maisara Caverns dungeon on any difficulty.", progress = "The Vilebranch usage of magic reeks of undead teachings... and I know that never ends well.", completion = "Never thought I'd feel good about saving trolls. The Witherbark better remember this act.", sourceObjectiveStatus = "unverified-source-field" }
quests[93755] = { id = 93755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den of Nalorakk", description = "A trial of skill and strength... I'd go myself if I wasn't needed in Silvermoon.\n\nGood luck, champion. I look forward to hearing about your victory against the Amani Loa of War.", sourceObjective = "Complete the Den of Nalorakk dungeon on any difficulty.", progress = "Didn't chicken out, did you? It's okay, your fear is not unfounded. Bears are the kings of nature. They'll mess you up.", completion = "An incredible feat. You have my respect, champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[93756] = { id = 93756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blinding Vale", description = "This place in Harandar is the Lightbloom's epicenter. Orweyna did what she could, which was much, but we must strike at the taproot of all roots for the plant to die.\n\nBe on your guard, even if you think yourself experienced with the Lightbloom by now. The vale is different from the rampant, but ultimately wild growth in Eversong. It's a calculated force of nature led by a Rootwarden who seeks to strangle you and everything else it desires.", sourceObjective = "Complete The Blinding Vale dungeon on any difficulty.", progress = "Learn what you can from the Lightbloom in Eversong, but beware this may be an entirely different set of problems. The Rootwarden will be expecting intruders such as yourself.", completion = "Does this victory spell the death of the Lightbloom? Only time will tell. But in my experience, life always finds a way.", sourceObjectiveStatus = "unverified-source-field" }
quests[93757] = { id = 93757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena", description = "If I didn't know that the domanaar thirst for battle, and all the pain and strife that comes with it, I'd say this is trap. Either way, I suppose it's an invitation to get yourself killed.\n\nIf you insist on participating in the Void's fighting games, I can't stop you. Just don't hesitate to kill as many voidspawn as possible while you're there, okay?", sourceObjective = "Complete the Voidscar Arena dungeon on any difficulty.", progress = "May your arrows strike true, champion.", completion = "You've bested them all! Well done, champion. Maybe I'll sign up next time! It sounded like fun.", sourceObjectiveStatus = "unverified-source-field" }
quests[93758] = { id = 93758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nexus-Point Xenas", description = "We must continue to keep an eye on this overpowered facility. If breached, disaster will spread beyond the Voidstorm. Unfortunately this magical and mechanical complex is beyond my area of expertise.\n\nPrepare yourself, and ensure that the Nexus-Point Xenas remains dormant.", sourceObjective = "Complete the Nexus-Point Xenas dungeon on any difficulty.", progress = "If the Nexus-Point is overloaded, it'll be a very quick death for many.\n\nLet's not entertain that thought any further. Secure the facility!", completion = "Swift work, champion. It seems like we'll have to continue our routine inspections, but for now, we can rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[93766] = { id = 93766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: World Quests", description = "The Void seeks to divide us, to drive a wedge between kin and kingdom alike. We cannot allow it.\n\nEverywhere I turn, I hear of those struggling--families displaced, defenders overwhelmed, healers stretched thin. No blade nor spell alone will turn this tide, but the strength of many hearts united can.\n\nGo forth and lend your aid where it is needed most.You will learn:", objectives = "Complete World Quests in Midnight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
